INSERT INTO books (book_id, title, author, genre, description, price, volume, cover, type, publisher, keywords, stock, page_count, release_date)
VALUES
  ('OP001', 'One Piece', 'Eiichiro Oda', 'Adventure, Fantasy', 'As a child, Monkey D. Luffy was inspired to become a pirate by listening to the tales of the buccaneer "Red-Haired" Shanks. But his life changed when Luffy accidentally ate the Gum-Gum Devil Fruit and gained the power to stretch like rubber...at the cost of never being able to swim again! Years later, still vowing to become the king of the pirates, Luffy sets out on his adventure...one guy alone in a rowboat, in search of the legendary "One Piece," said to be the greatest treasure in the world......Rated:T', 30, 'Vol 1', 'images/one_piece_vol_1.jpg', 'manga', 'Shueisha', 'pirates, treasure, friendship, award winning title', 10, 200, '1997-07-22'),
