  ('SL001', 'Solo Leveling', 'Chugong', 'Action, Fantasy', 'In a world where hunters battle deadly monsters emerging from mysterious gates, Jinwoo Sung is known as the weakest of them all. But when he''s left for dead in a hidden dungeon, he gains an incredible power—the ability to level up in strength beyond any known limits. Now, he must climb his way from E-rank to the top, one battle at a time.', 20, 'Vol 1', 'images/sl_vol_1.jpg', 'light novel', 'Yen Press', 'dungeon, hunter, leveling, power-up, bestsellers', 10, 192, '2021-03-02'),
  ('SL002', 'Solo Leveling', 'Chugong', 'Action, Fantasy', 'In a world where hunters battle deadly monsters emerging from mysterious gates, Jinwoo Sung is known as the weakest of them all. But when he''s left for dead in a hidden dungeon, he gains an incredible power—the ability to level up in strength beyond any known limits. Now, he must climb his way from E-rank to the top, one battle at a time.', 20, 'Vol 2', 'images/sl_vol_2.jpg', 'light novel', 'Yen Press', 'dungeon, hunter, leveling, power-up, bestsellers', 10, 192, '2021-07-20'),
  ('HXH001', 'Hunter x Hunter', 'Yoshihiro Togashi', 'Adventure', 'Gon Freecss aspires to become a Hunter, a specialist who takes on dangerous tasks such as discovering uncharted territories or locating rare items. He hopes to find his father, who is also a Hunter, and learn why he left him. Gon embarks on an adventure to become a Hunter and find his father.', 30, 'Vol 1', 'images/hxh_vol_1.jpg', 'manga', 'Shueisha', 'hunters, nen, exam, friendship, battles', 10, 192, '1998-06-04'),
  ('HXH002', 'Hunter x Hunter', 'Yoshihiro Togashi', 'Adventure', 'Gon Freecss aspires to become a Hunter, a specialist who takes on dangerous tasks such as discovering uncharted territories or locating rare items. He hopes to find his father, who is also a Hunter, and learn why he left him. Gon embarks on an adventure to become a Hunter and find his father.', 30, 'Vol 2', 'images/hxh_vol_2.jpg', 'manga', 'Shueisha', 'hunters, nen, exam, friendship, battles', 10, 192, '1998-09-04'),
