  ('TR001', 'Tokyo Revengers', 'Ken Wakui', 'Action', 'Takemichi Hanagaki is a 26-year-old freeter who learns that his ex-girlfriend, Hinata Tachibana, has been killed by the Tokyo Manji Gang. After a series of events, he finds himself traveling back in time to his middle school days, where he tries to save her and change the future.', 30, 'Vol 1', 'images/tr_vol_1.jpg', 'manga', 'Kodansha', 'time travel, gangs, revenge', 10, 192, '2017-03-01'),
  ('TR002', 'Tokyo Revengers', 'Ken Wakui', 'Action', 'Takemichi Hanagaki is a 26-year-old freeter who learns that his ex-girlfriend, Hinata Tachibana, has been killed by the Tokyo Manji Gang. After a series of events, he finds himself traveling back in time to his middle school days, where he tries to save her and change the future.', 30, 'Vol 2', 'images/tr_vol_2.jpg', 'manga', 'Kodansha', 'time travel, gangs, revenge', 10, 192, '2017-06-01'),
  ('JJK001', 'Jujutsu Kaisen', 'Gege Akutami', 'Action', 'Yuuta Okkotsu is a nervous high school student who is afflicted by a powerful curse. To save him, Satoru Gojo, a teacher at Jujutsu High School, takes him under his wing. As Yuuta learns to control his curse, he discovers the dark world of Jujutsu sorcerers and the battles they face against curses.', 30, 'Vol 1', 'images/jjk_vol_1.jpg', 'manga', 'Shueisha', 'curses, sorcerers, battles, bestsellers, animated series, award winning title', 10, 192, '2018-03-05'),
  ('JJK002', 'Jujutsu Kaisen', 'Gege Akutami', 'Action', 'Yuuta Okkotsu is a nervous high school student who is afflicted by a powerful curse. To save him, Satoru Gojo, a teacher at Jujutsu High School, takes him under his wing. As Yuuta learns to control his curse, he discovers the dark world of Jujutsu sorcerers and the battles they face against curses.', 30, 'Vol 2', 'images/jjk_vol_2.jpg', 'manga', 'Shueisha', 'curses, sorcerers, battles, bestsellers, animated series, award winning title', 10, 192, '2018-06-04'),
  ('AOT001', 'Attack on Titan', 'Hajime Isayama', 'Action', 'In a world where humanity resides within enormous walled cities to protect themselves from Titans, gigantic humanoid creatures, the story follows Eren Yeager and his friends who join the military to fight against the Titans after their city is invaded.', 50, 'Vol 1', 'images/aot_vol_1.jpg', 'manga', 'Kodansha', 'titans, war, survival, award winning title, animated series', 10, 192, '2009-09-09'),
