  ('DB001', 'Dragon Ball', 'Akira Toriyama', 'Action, Adventure, Comedy', 'Dragon Ball follows the adventures of Son Goku from his childhood through adulthood as he trains in martial arts and explores the world in search of the seven orbs known as Dragon Balls, which summon a wish-granting dragon when gathered.', 30, 'Vol 1', 'images/db_vol_1.jpg', 'manga', 'Shueisha', 'martial arts', 10, 192, '1984-09-20'),
  ('DB002', 'Dragon Ball', 'Akira Toriyama', 'Action, Adventure, Comedy', 'Dragon Ball follows the adventures of Son Goku from his childhood through adulthood as he trains in martial arts and explores the world in search of the seven orbs known as Dragon Balls, which summon a wish-granting dragon when gathered.', 30, 'Vol 2', 'images/db_vol_2.jpg', 'manga', 'Shueisha', 'martial arts', 10, 192, '1985-01-01'),
  ('DS001', 'Demon Slayer', 'Koyoharu Gotouge', 'Action', 'Learning to destroy demons won''t be easy, and Tanjiro barely knows where to start. The surprise appearance of another boy named Giyu, who seems to know what''s going on, might provide some answers—but only if Tanjiro can stop Giyu from killing his sister first!...Rated:T', 30, 'Vol 1', 'images/ds_vol_1.jpg', 'manga', 'Shueisha', 'demons, swords, family, bestsellers, animated series, award winning title', 10, 192, '2016-02-15'),
