  ('QQ001', 'The Quintessential Quintuplets', 'Negi Haruba', 'Romance, Comedy', 'Fuutarou Uesugi is a high school student who is hired as a tutor for the Nakano quintuplets, five identical sisters with distinct personalities. As he navigates their unique challenges, he finds himself entangled in their lives and develops feelings for them.', 25, 'Vol 1', 'images/tqq_vol_1.jpg', 'manga', 'Kodansha', 'school life, harem, siblings, quintuplets, love triangle, animated series, award winning title, bestsellers', 10, 192, '2017-08-17'),
  ('QQ002', 'The Quintessential Quintuplets', 'Negi Haruba', 'Romance, Comedy', 'Fuutarou Uesugi is a high school student who is hired as a tutor for the Nakano quintuplets, five identical sisters with distinct personalities. As he navigates their unique challenges, he finds himself entangled in their lives and develops feelings for them.', 25, 'Vol 2', 'images/tqq_vol_2.jpg', 'manga', 'Kodansha', 'school life, harem, siblings, quintuplets, love triangle, animated series, award winning title, bestsellers', 10, 192, '2017-11-17'),
  ('QQ003', 'The Quintessential Quintuplets', 'Negi Haruba', 'Romance, Comedy', 'Fuutarou Uesugi is a high school student who is hired as a tutor for the Nakano quintuplets, five identical sisters with distinct personalities. As he navigates their unique challenges, he finds himself entangled in their lives and develops feelings for them.', 25, 'Vol 3', 'images/tqq_vol_3.jpg', 'manga', 'Kodansha', 'school life, harem, siblings, quintuplets, love triangle, animated series, award winning title, bestsellers', 10, 192, '2018-02-16'),
  ('KAG001', 'Kaguya-sama: Love Is War', 'Aka Akasaka', 'Romance, Comedy', 'At the renowned Shuchiin Academy, student council president Miyuki Shirogane and vice president Kaguya Shinomiya are the perfect couple. But they refuse to confess their love for each other! Instead, they engage in a battle of wits to make the other confess first. Who will win this war of love?', 30, 'Vol 1', 'images/kaguya_vol_1.jpg', 'manga', 'Shueisha', 'romantic comedy, mind games, bestsellers, award winning title', 10, 192, '2015-05-19'),
  ('KAG002', 'Kaguya-sama: Love Is War', 'Aka Akasaka', 'Romance, Comedy', 'At the renowned Shuchiin Academy, student council president Miyuki Shirogane and vice president Kaguya Shinomiya are the perfect couple. But they refuse to confess their love for each other! Instead, they engage in a battle of wits to make the other confess first. Who will win this war of love?', 30, 'Vol 2', 'images/kaguya_vol_2.jpg', 'manga', 'Shueisha', 'romantic comedy, mind games, bestsellers, award winning title', 10, 192, '2015-08-18'),
  ('HOR001', 'Horimiya', 'Hero', 'Romance, Slice of Life', 'A sweet "aww"-inspiring tale of school life begins!! At school, Kyouko Hori is known for being smart, attractive, and popular. On the other hand, her classmate, the boring, gloomy Izumi Miyamura tends to get painted as a "loser fanboy." But when a liberally pierced and tattooed (not to mention downright gorgeous) Miyamura appears unexpectedly on the doorstep of secretly plain-Jane homebody Hori, these two similarly dissimilar teenagers discover that there are multiple sides to every story...and person!', 30, 'Vol 1', 'images/horimiya_vol_1.jpg', 'manga', 'Yen Press', 'high school', 10, 192, '2011-10-18'),
  ('HOR002', 'Horimiya', 'Hero', 'Romance, Slice of Life', 'A sweet "aww"-inspiring tale of school life begins!! At school, Kyouko Hori is known for being smart, attractive, and popular. On the other hand, her classmate, the boring, gloomy Izumi Miyamura tends to get painted as a "loser fanboy." But when a liberally pierced and tattooed (not to mention downright gorgeous) Miyamura appears unexpectedly on the doorstep of secretly plain-Jane homebody Hori, these two similarly dissimilar teenagers discover that there are multiple sides to every story...and person!', 30, 'Vol 2', 'images/horimiya_vol_2.jpg', 'manga', 'Yen Press', 'high school', 10, 192, '2012-01-17'),
  ('YLIA001', 'Your Lie in April', 'Naoshi Arakawa', 'Romance, Drama', 'Kōsei Arima was a piano prodigy until the death of his mother, which left him unable to hear the sound of his own playing. He meets Kaori Miyazono, a spirited violinist who helps him rediscover his love for music.', 50, 'Vol 1', 'images/ylia_vol_1.jpg', 'manga', 'Kodansha', 'music, love', 10, 192, '2011-04-06'),
  ('YLIA002', 'Your Lie in April', 'Naoshi Arakawa', 'Romance, Drama', 'Kōsei Arima was a piano prodigy until the death of his mother, which left him unable to hear the sound of his own playing. He meets Kaori Miyazono, a spirited violinist who helps him rediscover his love for music.', 50, 'Vol 2', 'images/ylia_vol_2.jpg', 'manga', 'Kodansha', 'music, love', 10, 192, '2011-07-06'),
  ('DIMH001', 'The Dangers in My Heart', 'Norio Sakurai', 'Romance, Comedy, Slice of Life', 'Ichikawa Kyotaro, a boy barely clinging to the bottom rung of his school''s social ladder, secretly believes he''s the tortured lead in some psychological thriller. He spends his days dreaming up ways to disrupt his classmates'' peaceful lives and pining after Yamada Anna, the class idol. But Ichikawa''s not nearly the troubled teen he pretends to be...and it turns out Yamada''s a bit odd herself!', 28, 'Vol 1', 'images/dimh_vol_1.jpg', 'manga', 'Kodansha', 'school life, psychological', 10, 192, '2018-04-04'),
  ('BB001', 'Blue Box', 'Kouji Miura', 'Romance', 'Taiki Inomata, a third-year student in junior high, attends Eimei Academy, an integrated school with a major sports program. Having joined the high school badminton team, Taiki tries to attend open practice as early as possible. But no matter how early he goes, he always arrives second in the gymnasium. The person one step ahead of him is Chinatsu Kano, a first-year student in senior high and Taiki''s crush.', 13, 'Vol 1', 'images/bb_vol_1.jpg', 'manga', 'Shueisha', 'basketball, romance, shounen, school life, animated series, bestsellers', 10, 192, '2021-04-05'),
